package com.bechir.system;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import android.text.*;import java.util.*;
public class MainActivity extends Activity {
 LinearLayout root,grid,header; boolean drawer=false; float down; android.content.SharedPreferences prefs; EditText search; TextClock clock;
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 GradientDrawable bg(int c,int radius){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(radius));d.setStroke(dp(1),0x447ccfff);return d;}
 TextView label(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.WHITE);t.setGravity(17);return t;}
 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("launcher",0);getWindow().setStatusBarColor(0xff071321);getWindow().setNavigationBarColor(0xff071321);
 root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(16),dp(18),dp(16),dp(12));root.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff071321,0xff102e50,0xff071321}));setContentView(root);
 header=new LinearLayout(this);header.setOrientation(1);root.addView(header);TextView brand=label("B E C H I R   /   O N E",14);brand.setLetterSpacing(.14f);brand.setTextColor(0xffa9d9ff);header.addView(brand);clock=new TextClock(this);clock.setFormat24Hour("HH:mm");clock.setFormat12Hour("HH:mm");clock.setTextSize(82);clock.setTypeface(android.graphics.Typeface.create("sans-serif-thin",0));clock.setPadding(0,dp(22),0,0);clock.setTextColor(0xff70caff);clock.setGravity(17);header.addView(clock);
 TextClock date=new TextClock(this);date.setFormat24Hour("dd / MM / yyyy");date.setFormat12Hour("dd / MM / yyyy");date.setTextColor(Color.WHITE);date.setGravity(17);header.addView(date);TextView welcome=label("مساحتك الخاصة  •  عالمك الخاص",14);welcome.setTextColor(0xffb4c9e9);welcome.setPadding(0,dp(12),0,dp(22));header.addView(welcome);
 Button home=new Button(this);home.setText("⚙");home.setBackground(bg(0xff203b55,24));home.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("الإعدادات").setItems(new String[]{"تعيين الواجهة الرئيسية","خلفية زرقاء","خلفية سوداء"},(d,n)->{if(n==0)startActivity(new Intent(android.provider.Settings.ACTION_HOME_SETTINGS));else{prefs.edit().putBoolean("black",n==2).apply();paint();}}).show());LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(dp(48),dp(48));hp.gravity=Gravity.CENTER;header.addView(home,hp);paint();
 search=new EditText(this);search.setSingleLine(true);search.setHint("ابحث عن تطبيق");search.setTextColor(Color.WHITE);search.setHintTextColor(0xffaabbcc);search.setPadding(dp(16),dp(8),dp(16),dp(8));search.setBackground(bg(0xff203b55,20));root.addView(search,new LinearLayout.LayoutParams(-1,dp(50)));
 ScrollView scroll=new ScrollView(this);grid=new LinearLayout(this);grid.setOrientation(1);scroll.addView(grid);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
 LinearLayout dock=new LinearLayout(this);dock.setGravity(Gravity.CENTER);dock.setPadding(dp(8),dp(8),dp(8),dp(8));dock.setBackground(bg(0x553c6799,28));String[] symbols={"☎","✉","◉","◎"};String[] actions={Intent.ACTION_DIAL,Intent.ACTION_SENDTO,android.provider.MediaStore.INTENT_ACTION_STILL_IMAGE_CAMERA,Intent.ACTION_VIEW};for(int k=0;k<4;k++){final int j=k;TextView shortcut=label(symbols[k],29);dock.addView(shortcut,new LinearLayout.LayoutParams(0,dp(48),1));shortcut.setOnClickListener(v->{try{Intent in=new Intent(actions[j]);if(j==1)in.setData(android.net.Uri.parse("smsto:"));if(j==3)in.setData(android.net.Uri.parse("https://www.google.com"));startActivity(in);}catch(Exception ex){Toast.makeText(this,"التطبيق غير متوفر",0).show();}});}root.addView(dock);TextView toggle=label("⌃   جميع التطبيقات",16);toggle.setBackground(bg(0x332b588c,24));root.addView(toggle,new LinearLayout.LayoutParams(-1,dp(54)));toggle.setOnClickListener(v->switchPage(!drawer));search.setVisibility(View.GONE);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){render();}public void afterTextChanged(Editable e){}});render();}
 protected void onResume(){super.onResume();if(grid!=null)render();}
 void render(){grid.removeAllViews();PackageManager pm=getPackageManager();Intent q=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER);List<ResolveInfo> apps=pm.queryIntentActivities(q,0);apps.sort((a,b)->a.loadLabel(pm).toString().compareToIgnoreCase(b.loadLabel(pm).toString()));LinearLayout row=null;int i=0;for(ResolveInfo a:apps){String name=a.loadLabel(pm).toString();if((!drawer&&!prefs.getBoolean("fav:"+a.activityInfo.packageName,false))||a.activityInfo.packageName.equals(getPackageName())||!name.toLowerCase(Locale.ROOT).contains(search.getText().toString().toLowerCase(Locale.ROOT)))continue;if(i++%4==0){row=new LinearLayout(this);grid.addView(row);}LinearLayout tile=new LinearLayout(this);tile.setOrientation(1);tile.setGravity(17);tile.setPadding(dp(3),dp(10),dp(3),dp(10));row.addView(tile,new LinearLayout.LayoutParams(0,dp(100),1));ImageView icon=new ImageView(this);icon.setImageDrawable(a.loadIcon(pm));icon.setBackground(bg(0x223d6599,18));icon.setPadding(dp(5),dp(5),dp(5),dp(5));tile.addView(icon,new LinearLayout.LayoutParams(dp(58),dp(58)));TextView title=label(name,12);title.setMaxLines(2);tile.addView(title);tile.setOnLongClickListener(v->{String k="fav:"+a.activityInfo.packageName;boolean old=prefs.getBoolean(k,false);prefs.edit().putBoolean(k,!old).apply();Toast.makeText(this,old?"أزيل من المفضلة":"أضيف إلى الشاشة الرئيسية",0).show();if(!drawer)render();return true;});tile.setOnClickListener(v->{try{Intent launch=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setClassName(a.activityInfo.packageName,a.activityInfo.name).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(launch);}catch(Exception e){Toast.makeText(this,"تعذر فتح التطبيق",0).show();}});}if(row!=null)while(i++%4!=0)row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));}
void paint(){root.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,prefs.getBoolean("black",false)?new int[]{0xff050608,0xff171b23}:new int[]{0xff050918,0xff173e79,0xff382b69,0xff070c1d}));}
void switchPage(boolean value){drawer=value;header.setVisibility(value?View.GONE:View.VISIBLE);search.setVisibility(value?View.VISIBLE:View.GONE);if(!value){search.setText("");((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(search.getWindowToken(),0);}render();}
@Override public boolean dispatchTouchEvent(android.view.MotionEvent e){if(e.getAction()==0)down=e.getY();if(e.getAction()==1&&!drawer&&down-e.getY()>dp(90)){switchPage(true);return true;}return super.dispatchTouchEvent(e);}
@Override public void onBackPressed(){if(drawer)switchPage(false);else super.onBackPressed();}
@Override protected void onNewIntent(Intent i){super.onNewIntent(i);switchPage(false);}
}